     1|export type OwnerLocationClarificationIntent = 'ambiguous_where_are_we' | 'physical_location_unavailable';
     2|
     3|export type IVXOwnerAISemanticIntent =
     4|  | 'time_query'
     5|  | 'ambiguous_location'
     6|  | 'physical_location_unavailable'
     7|  | 'project_status'
     8|  | 'long_structured_response'
     9|  | 'multi_step_task'
    10|  | 'deal_review'
    11|  | 'bug_review'
    12|  | 'code_retrieval'
    13|  | 'explicit_tool_request'
    14|  | 'app_build_planning'
    15|  | 'app_generator_execution'
    16|  | 'self_developer_execution'
    17|  | 'daily_self_improvement'
    18|  | 'media_generation_3d'
    19|  | 'normal_question';
    20|
    21|export type IVXOwnerAIRouteDecision = 'clarification' | 'time_tool' | 'tool_grounded_gpt' | 'self_developer' | 'self_improvement' | 'gpt_conversation' | 'app_generator';
    22|
    23|export type IVXOwnerAIPlannerDecision = {
    24|  semanticIntent: IVXOwnerAISemanticIntent;
    25|  route: IVXOwnerAIRouteDecision;
    26|  useTools: boolean;
    27|  toolHints: string[];
    28|  requiresLongResponse: boolean;
    29|  requiresTaskDecomposition: boolean;
    30|  memoryMode: 'load_recent_and_persist_turn';
    31|  fallbackPolicy: 'fail_visible_not_canned';
    32|  reason: string;
    33|};
    34|
    35|function normalizePrompt(prompt: string): string {
    36|  return prompt.trim().toLowerCase().replace(/\s+/g, ' ');
    37|}
    38|
    39|/**
    40| * Deterministic exact-echo command detector (acceptance test B).
    41| *
    42| * When the owner sends an explicit "reply/respond/say exactly: <X>" instruction,
    43| * IVX must return <X> VERBATIM — proving the LATEST owner message is the one being
    44| * executed, with no LLM paraphrasing, no clarification hijack, and no truncation.
    45| * Returns the exact text to echo (preserving original casing/characters), or null.
    46| */
    47|export function resolveExactEchoCommand(prompt: string): string | null {
    48|  const raw = prompt.trim();
    49|  if (!raw) {
    50|    return null;
    51|  }
    52|  // Match: reply/respond/answer/say/repeat/echo [back] exactly [with][:] <payload>
    53|  const match = raw.match(/^(?:please\s+)?(?:reply|respond|answer|say|repeat|echo|output|return|print)\s+(?:back\s+)?exactly(?:\s+with)?\s*[:\-]?\s*([\s\S]+)$/i);
    54|  if (!match) {
    55|    return null;
    56|  }
    57|  let payload = match[1].trim();
    58|  // Strip a single pair of wrapping quotes the owner may have added around the payload.
    59|  const quoted = payload.match(/^(["'\u201c\u2018])([\s\S]+)(["'\u201d\u2019])$/);
    60|  if (quoted) {
    61|    payload = quoted[2].trim();
    62|  }
    63|  return payload.length > 0 ? payload : null;
    64|}
    65|
    66|/**
    67| * Diagnostic-intent guard — mirrors the client-side ivxOwnerIntentClassifier.
    68| *
    69| * A prompt that starts with or leads with a diagnostic question
    70| * ("audit the loading problem...", "why is the chat...", "explain what is wrong")
    71| * must NEVER be routed to the senior developer worker, even if it ends with
    72| * "deploy it" / "fix it" / "and ship it". The owner's reported bug was exactly
    73| * this: "Audit the loading problem on this chat, explain what is wrong, what
    74| * must be fixed, and deploy it" matched the deploy/fix execution signals and
    75| * was misrouted to the worker, which returned progress percentages instead of
    76| * a real diagnosis. Diagnostic intent takes PRIORITY over execution intent.
    77| */
    78|function isDiagnosticLeadingIntent(normalized: string): boolean {
    79|  // Leading diagnostic verbs: the prompt opens with an audit/diagnosis/explain request.
    80|  // We only match at the start of the prompt (first ~120 chars) so a later
    81|  // "...and audit the result" clause inside a long build task does not hijack it.
    82|  const head = normalized.slice(0, 160);
    83|  const leadsWithDiagnostic = /^(?:please\s+)?(?:audit|diagnose|diagnosis|diagnostic|explain|why\s+is|why\s+does|why\s+doesn't|what\s+is\s+wrong|what's\s+wrong|what\s+is\s+broken|what's\s+broken|investigate|trace|root\s+cause|figure\s+out\s+why|tell\s+me\s+why|tell\s+me\s+what\s+is\s+wrong|tell\s+me\s+what's\s+wrong)\b/i.test(head);
    84|  if (leadsWithDiagnostic) {
    85|    return true;
    86|  }
    87|  // Explicit diagnostic phrasing anywhere in the prompt that pairs an inspection
    88|  // verb with a "loading / broken / wrong / failing" symptom and an explanation ask.
    89|  const hasInspectionVerb = /\b(audit|diagnose|diagnosis|diagnostic|investigate|trace|root\s+cause|figure\s+out)\b/i.test(normalized);
    90|  const hasSymptom = /\b(loading|load\s+problem|blank|frozen|spinner|slow|stuck|broken|wrong|failing|crash|hangs?|won't\s+load|doesn't\s+load|not\s+loading)\b/i.test(normalized);
    91|  const asksForExplanation = /\b(explain|tell\s+me|what\s+is\s+wrong|what's\s+wrong|why\s+is|why\s+does|root\s+cause)\b/i.test(normalized);
    92|  return hasInspectionVerb && hasSymptom && asksForExplanation;
    93|}
    94|
    95|/**
    96| * Detects a long, structured owner EXECUTION command or task block (e.g.
    97| * "BLOCK 28 Visitor-to-Investor Conversion Engine / Create: ... / Track: ...").
    98| *
    99| * These must NEVER be hijacked by short clarification intents (physical location,
   100| * time, manual-answer, infrastructure-runtime) just because the spec happens to
   101| * mention a keyword like "location", "backend", or "runtime" inside a much larger
   102| * instruction. The whole class of "IVX answered the wrong context" bugs comes from
   103| * a clarification regex matching a single word inside a long command and short-
   104| * circuiting before execution routing. When this returns true, the planner routes
   105| * the command to task decomposition and the handler skips every clarification gate.
   106| */
   107|export function isOwnerExecutionOrTaskBlock(prompt: string): boolean {
   108|  const raw = prompt.trim();
   109|  if (!raw) {
   110|    return false;
   111|  }
   112|  const normalized = normalizePrompt(prompt);
   113|
   114|  // DIAGNOSTIC PRIORITY: a prompt that leads with an audit/diagnose/explain request
   115|  // must never be treated as an execution/task block, even if it contains deploy/fix/commit
   116|  // signals later. The owner's "Audit the loading problem... and deploy it" was misrouted
   117|  // here, returning worker progress instead of a real diagnosis. This guard runs FIRST.
   118|  if (isDiagnosticLeadingIntent(normalized)) {
   119|    return false;
   120|  }
   121|
   122|  // Explicit "BLOCK N" / "STEP N" / "PHASE N" task headers are always task blocks.
   123|  if (/\b(block|step|phase)\s*\d+\b/.test(normalized)) {
   124|    return true;
   125|  }
   126|
   127|  // Structured spec markers the owner uses for feature/task blocks.
   128|  const specMarkerCount = (raw.match(/^\s*(create|track|stages?|capabilities|dashboard|requirements?|safety|store|return|show|build|objective|audit|capabilities?|metrics?)\s*:/gim) ?? []).length;
   129|  if (specMarkerCount >= 2) {
   130|    return true;
   131|  }
   132|
   133|  // Multi-line, sufficiently long instructions are treated as task blocks so a
   134|  // single keyword can never reroute them to a one-line clarification answer.
   135|  const lineCount = raw.split(/\n/).filter((line) => line.trim().length > 0).length;
   136|  if (raw.length >= 320 && lineCount >= 4) {
   137|    return true;
   138|  }
   139|
   140|  // Imperative engine/system/feature build commands ("... Conversion Engine",
   141|  // "build the ... system") that are also reasonably long.
   142|  if (raw.length >= 90 && /\b(engine|system|pipeline|module|platform|dashboard|workflow)\b/.test(normalized) && /\b(create|build|implement|add|wire|ship|deploy|design|develop)\b/.test(normalized)) {
   143|    return true;
   144|  }
   145|
   146|  // Production-execution signals — explicit owner commands to commit/push/deploy/
   147|  // verify on this system. These must NEVER be hijacked by short-circuit
   148|  // clarification gates (time/date, location, manual-answer) just because the
   149|  // prompt happens to contain a date phrase like "(today's date)" inside a larger
   150|  // deploy instruction. This closes the chat→worker narrative-only fallback gap:
   151|  // a prompt like "Bump the version marker to ...-2026-07-19 (today's date), commit
   152|  // to GitHub, deploy to Render, verify /health" must route to the developer
   153|  // executor, not return "The answer is 2019." as a math/time query.
   154|  const hasCommitSignal = /\b(commit|push\s+(?:to\s+)?github|github\s+main|pr\s*#\d)\b/.test(normalized);
   155|  const hasDeploySignal = /\b(deploy|render|trigger\s+a\s+deploy|live\s+commit|production\s+commit)\b/.test(normalized);
   156|  const hasVerifySignal = /\b(verify|verified\s+evidence|verify\s+the\s+live|live\s+runtime\s+commit|github\s+head|sha\s+match|\/health)\b/.test(normalized);
   157|  const hasMutationSignal = /\b(bump|update|change|edit|modify|patch|fix|migrate|rollback)\b/.test(normalized)
   158|    && /\b(version|marker|file|endpoint|route|table|policy|config|code|production)\b/.test(normalized);
   159|  const executionSignalCount = [hasCommitSignal, hasDeploySignal, hasVerifySignal, hasMutationSignal].filter(Boolean).length;
   160|  if (executionSignalCount >= 2) {
   161|    return true;
   162|  }
   163|
   164|  // App-scaffold / new-app-from-scratch signals — explicit owner commands to
   165|  // CREATE a new app, scaffold a new project, build a new module from scratch,
   166|  // or run a stress/load test. These are real code-production requests the
   167|  // senior developer worker handles (create_file patch operations), NOT
   168|  // planning/narrative prompts. Without this guard, the planner mis-routes
   169|  // them to app_build_planning → gpt_conversation (narrative GPT-4o answer)
   170|  // and the senior developer never runs. Closes the PARTIAL item gap where
   171|  // "create a new app from scratch" returned a narrative plan instead of
   172|  // real scaffolded files.
   173|  const hasAppScaffoldSignal = /\b(?:create|scaffold|build|generate)\s+(?:a\s+)?(?:new\s+)?(?:app|application|module|service)\s+(?:from\s+scratch|project|skeleton|shell|template|called\s+|named\s+)/i.test(normalized)
   174|    || /\bnew\s+app\s+from\s+scratch/i.test(normalized)
   175|    || /\bscaffold\s+(?:a\s+)?(?:new\s+)?(?:app|project|module)/i.test(normalized);
   176|  const hasStressTestSignal = /\bstress\s*test/i.test(normalized)
   177|    || /\bload\s*test/i.test(normalized)
   178|    || /\brun\s+a\s+(?:stress|load)\s+test/i.test(normalized);
   179|  if (hasAppScaffoldSignal || hasStressTestSignal || isServerBugFixRequest(normalized) || asksToCreateAndShowProof(normalized)) {
   180|    return true;
   181|  }
   182|
   183|  return false;
   184|}
   185|
   186|function asksForLongStructuredResponse(normalized: string): boolean {
   187|  return /\b(full\s+list|complete\s+list|list\s+all|enumerate|from\s+1\s+to\s+\d+|1\s*[-–to]+\s*\d+|one\s+to\s+\d+|\d{2,}\s+(?:items?|points?|things?|steps?|rows?|entries|checks?))\b/.test(normalized)
   188|    // Full / structured audits always need the long-response budget + auto-continuation.
   189|    || /\b(full\s+audit|complete\s+audit|end[-\s]?to[-\s]?end\s+audit|audit\s+(?:everything|all|end\s+to\s+end|one\s+by\s+one)|run\s+(?:a\s+)?full\s+audit|audit\s+\d{1,4}\s*[-–to]+\s*\d{1,4}|audit\s+from\s+1)\b/.test(normalized)
   190|    // Any explicit numeric range whose upper bound is large (e.g. "1-100", "1 to 2000").
   191|    || hasLargeExplicitRange(normalized);
   192|}
   193|
   194|export function hasLargeExplicitRange(normalized: string): boolean {
   195|  const match = normalized.match(/\b(?:from\s+)?1\s*(?:[-–]|to)\s*(\d{2,4})\b/);
   196|  if (match) {
   197|    const upper = Number.parseInt(match[1], 10);
   198|    return Number.isFinite(upper) && upper >= 30;
   199|  }
   200|  return false;
   201|}
   202|
   203|function asksForMultiStepTask(normalized: string): boolean {
   204|  return /\b(step[-\s]?by[-\s]?step|multi[-\s]?step|decompose|break\s+(?:it|this)?\s*down|task\s+decomposition|execution\s+plan|implementation\s+plan|roadmap|sequence)\b/.test(normalized)
   205|    || /\b(build|fix|audit|implement|ship|repair|improve)\b.{0,80}\b(plan|steps|phases|tasks)\b/.test(normalized);
   206|}
   207|
   208|export function asksForDealReview(normalized: string): boolean {
   209|  return /\b(review\s+(?:this\s+)?deal|deal\s+review|underwrite|underwriting|cap\s+rate|noi|cash[-\s]?on[-\s]?cash|real\s+estate\s+deal|investment\s+deal)\b/.test(normalized);
   210|}
   211|
   212|export function asksForBugReview(normalized: string): boolean {
   213|  return /\b(what\s+bugs?\s+do\s+you\s+see|find\s+bugs?|bug\s+review|bug\s+list|prioritized\s+bug\s+list|review\s+(?:the\s+)?bugs?|errors?\s+do\s+you\s+see|what\s+is\s+broken)\b/.test(normalized)
   214|    || /\binspect\b.{0,100}\b(?:chat|ai|assistant)\b.{0,100}\bbugs?\b/.test(normalized);
   215|}
   216|
   217|/**
   218| * Detects when the owner wants to SEE real source code from the repository —
   219| * file paths, functions, endpoints, queries, or a feature's implementation —
   220| * rather than execute a build/fix task. These requests must be grounded in the
   221| * live repo (code search) so the answer contains concrete files and source,
   222| * never a generic LLM guess or a clarification question.
   223| */
   224|export function asksForCodeRetrieval(normalized: string): boolean {
   225|  const codeNoun = /\b(code|source|source\s+code|snippet|implementation|function|method|class|file|files|file\s+path|endpoint|route|api\s+route|handler|query|queries|sql\s+quer(?:y|ies)|service|module|component|schema\s+definition)\b/;
   226|  const retrievalVerb = /\b(show|give|return|see|read|display|paste|get|list|find|reveal|provide|where\s+is|which\s+file|what\s+file|locate|share)\b/;
   227|  // "show me the analytics code", "return the analytics implementation", "where is the auth endpoint"
   228|  if (retrievalVerb.test(normalized) && codeNoun.test(normalized)) {
   229|    return true;
   230|  }
   231|  // Direct phrasings that always imply real code retrieval.
   232|  return /\b(source\s+code|code\s+for|implementation\s+of|implementation\s+details|actual\s+code|real\s+code|how\s+is\s+\w+\s+implemented|how\s+does\s+\w+\s+work\s+in\s+(?:the\s+)?code|file\s+path|function\s+name|endpoint\s+definition|database\s+quer(?:y|ies)\s+used)\b/.test(normalized);
   233|}
   234|
   235|/**
   236| * Detects open-ended app/product build requests like "build an app like TikTok",
   237| * "create a clone of Uber", "I want to build a marketplace app". These must NOT
   238| * fall through to a generic conversational timeline. They trigger a senior product-
   239| * engineering planning response: architecture proposal, module breakdown, required
   240| * repo/actions, execution plan, and a permission/capability check — not boilerplate.
   241| *
   242| * Deliberately excludes prompts that already point at THIS repo's concrete work
   243| * ("build the feature", "build this screen"), which belong to self-developer execution.
   244| */
   245|/**
   246| * Detects an owner request to GENERATE a 3D model / mesh / render (e.g.
   247| * "generate a 3d model of a villa", "create a 3D render of our product",
   248| * "make me a 3d mesh of a chair"). Routes to the owner 3D generation tool
   249| * (Meshy/Tripo direct, or a deterministic procedural Three.js preview).
   250| *
   251| * Deliberately excludes "build an app" / generic build requests by requiring an
   252| * explicit 3D/mesh/render target word.
   253| */
   254|export function asksToGenerate3DModel(normalized: string): boolean {
   255|  const genVerb = /\b(generate|create|make|build|render|design|produce|model|sculpt|give\s+me|i\s+want|i\s+need)\b/;
   256|  const threeDTarget = /\b(3d|three[\s-]?d)\b/;
   257|  const meshTarget = /\b(3d\s+model|3d\s+render|3d\s+mesh|3d\s+object|3d\s+asset|mesh|render)\b/;
   258|  if (!genVerb.test(normalized)) {
   259|    return false;
   260|  }
   261|  if (threeDTarget.test(normalized)) {
   262|    return true;
   263|  }
   264|  // "model/mesh/render" without "3d" only counts when paired with a clear object word.
   265|  return meshTarget.test(normalized) && /\b(model|mesh|render|object|asset|figure|statue|product|prototype|scene)\b/.test(normalized);
   266|}
   267|
   268|/**
   269| * Detects a short, imperative server bug/crash/fix request that must execute
   270| * via the senior-developer runtime rather than fall through to a conversational
   271| * GPT answer. Catches prompts like "fix server crash", "server is down", "fix
   272| * the server issue", "resolve the backend crash" — these are concrete in-repo
   273| * engineering tasks, not general questions. Without this signal the prompt is
   274| * too short to register as a task block and the reliability gate blocks the
   275| * GPT answer with a contradictory STATE: BLOCKED message.
   276| */
   277|export function isServerBugFixRequest(normalized: string): boolean {
   278|  // Imperative "fix server ..." / "fix the server ..." / "fix backend/api ..."
   279|  const fixServer = /\bfix\s+(?:the\s+)?(?:server|backend|api)\b/i.test(normalized);
   280|  // Declarative server/backend/api crash / is down / outage / failure / error
   281|  const serverIncident = /\b(?:server|backend|api)\s+(?:is\s+|are\s+)?(?:crash|crashes|crashed|down|outage|offline|failing|failure|failures|error|errors|bug|bugs|issue|issues)\b/i.test(normalized);
   282|  // Imperative "fix server crash" / "fix backend outage" / "fix api error" (with specific noun)
   283|  const fixServerSpecific = /\bfix\s+(?:the\s+)?(?:server|backend|api)\s+(?:crash|crashes|outage|error|errors|failure|failures|issue|issues|bug|bugs)\b/i.test(normalized);
   284|  return fixServer || serverIncident || fixServerSpecific;
   285|}
   286|
   287|/**
   288| * Detects owner prompts that demand a real creation/build be shown/proven in the chat
   289| * (e.g. "create and show me a chat module", "build me a feature and prove it",
   290| * "make the developer text and show me"). These are execution commands, not status
   291| * questions or tutorial requests. The phrase "I want to see if you are senior developer"
   292| * was wrongly answered with a static capability description because the router did not
   293| * recognize the first half of the message as an execution signal. This detector closes
   294| * that gap: when a create/build verb and a show/proof verb both appear with a code/UI
   295| * target, the senior-developer runtime executes end-to-end and returns live proof.
   296| */
   297|export function asksToCreateAndShowProof(normalized: string): boolean {
   298|  // A "how to" / tutorial request is informational, not an execution command.
   299|  if (/\bhow\s+to\b/.test(normalized)) {
   300|    return false;
   301|  }
   302|  const createVerb = /\b(create|make|build|code|develop|implement|add|wire|generate|write|design)\b/;
   303|  const showProof = /\b(show|prove|demonstrate|display|see|deploy|ship|verify|give\s+me)\b/;
   304|  const target = /\b(chat|module|component|screen|feature|fix|app|page|text|developer|backend|api|route|function|file|code|ui|dashboard|engine|pipeline|system|platform|workflow|bug|issue|error|patch|feature|interface)\b/;
   305|  if (!createVerb.test(normalized) || !target.test(normalized)) {
   306|    return false;
   307|  }
   308|  // "create X and show me" / "build X and prove it" / "make X and deploy it"
   309|  const createAndShow = /\b(?:create|make|build|code|develop|implement|add|wire|generate|write|design)\b.{0,80}\b(?:and|then)\s+(?:show|prove|demonstrate|display|deploy|ship|verify)\b/i.test(normalized);
   310|  // "show me the X you create" / "I want to see X created/built" / "give me the X"
   311|  const showThenCreate = showProof.test(normalized) && /\b(?:you|it|this|that|the)\s+(?:create|build|make|code|develop|implement|add|generate|write|design)\b/i.test(normalized);
   312|  // "I want to see if you can create/build X" / "see if you can make X" (screenshot prompt)
   313|  const wantToSeeCreation = /\b(?:i\s+want\s+to\s+see|see\s+if)\s+(?:you\s+)?(?:can\s+)?(?:create|build|make|code|develop|implement|write|design)\b/i.test(normalized)
   314|    || /\b(?:create|build|make|code|develop|implement|write|design)\b.{0,60}\b(?:and\s+show|and\s+prove|and\s+deploy|to\s+show|to\s+prove|to\s+deploy)\b/i.test(normalized);
   315|  return createAndShow || showThenCreate || wantToSeeCreation;
   316|}
   317|
   318|export function asksToBuildApp(normalized: string): boolean {
   319|  // "build/create/make/design/develop ... an/a/another ... app/clone/platform/product/mvp/saas/marketplace/..."
   320|  const buildVerb = /\b(build|create|make|design|develop|spin\s+up|launch|clone|ship)\b/;
   321|  const appNoun = /\b(app|application|clone|platform|product|mvp|saas|marketplace|startup|website|web\s+app|mobile\s+app|social\s+(?:app|network|platform)|dating\s+app|delivery\s+app|fintech\s+app)\b/;
   322|  // "like X" / "such as X" / "similar to X" / "version of X" / "clone of X" strongly implies product planning.
   323|  const comparativeApp = /\b(?:app|clone|platform|product|version|something)\b[^.]{0,40}\b(?:like|similar\s+to|such\s+as)\b/;
   324|  const cloneOf = /\b(clone|version|copy)\s+of\s+\w+/;
   325|
   326|  // A build command aimed at the owner's OWN IVX system ("build the IVX engine",
   327|  // "create our investment platform", "finish the autonomous engine") is in-repo
   328|  // EXECUTION, not a request to scaffold a brand-new external product. It must never
   329|  // enter narrative "app planning" mode — it routes to the senior-developer runtime.
   330|  if (targetsOwnSystemBuild(normalized)) {
   331|    return false;
   332|  }
   333|  if (cloneOf.test(normalized) || comparativeApp.test(normalized)) {
   334|    return true;
   335|  }
   336|  if (buildVerb.test(normalized) && appNoun.test(normalized)) {
   337|    // Avoid hijacking concrete in-repo execution like "build the screen"/"build this feature".
   338|    const pointsAtThisRepoWork = /\b(this|that|the)\s+(feature|screen|fix|bug|endpoint|route|module|component|migration|page|function|test)\b/.test(normalized);
   339|    return !pointsAtThisRepoWork;
   340|  }
   341|  return false;
   342|}
   343|
   344|/**
   345| * Detects a build/execute command aimed at the owner's OWN IVX system rather than a
   346| * brand-new external app. These are concrete in-repo engineering jobs ("build the IVX
   347| * autonomous engine", "create our investor pipeline", "finish the conversion engine",
   348| * "implement the IVX dashboard module") and must EXECUTE end-to-end via the senior-
   349| * developer runtime — never get answered with an "Architecture Proposal / Phase 1-4"
   350| * narrative. The signal is a build verb plus either an explicit "IVX"/"our"/"my"
   351| * possessive or a system-component noun (engine, pipeline, module, workflow, dashboard,
   352| * system, platform) describing THIS product.
   353| */
   354|export function targetsOwnSystemBuild(normalized: string): boolean {
