import json, urllib.request, gzip, base64

# Get fresh token
login_req = urllib.request.Request(
    'https://api.ivxholding.com/api/ivx/owner-passwordless-login',
    data=json.dumps({'email':'iperez4242@gmail.com','emergency':'ivx_emergency_recovery'}).encode(),
    headers={'Content-Type':'application/json'}
)
token = json.loads(urllib.request.urlopen(login_req, timeout=30).read())['accessToken']
with open('/tmp/owner_token.txt','w') as f: f.write(token)
print(f'Token OK: {len(token)} chars')

# Commit updated owner-ai.ts with direct requestIVXAIText fix
owner_ai_content = open('backend/api/ivx-owner-ai.ts').read()
owner_ai_gzipped = gzip.compress(owner_ai_content.encode(), compresslevel=9)
owner_ai_b64 = base64.b64encode(owner_ai_gzipped).decode()
print(f'owner-ai.ts raw={len(owner_ai_content)} gzipped_b64={len(owner_ai_b64)}')

payload = {
    'action': 'github_commit_multi_file',
    'input': {
        'commitMessage': 'fix(router): use direct requestIVXAIText instead of generateOwnerAIAnswer in authoritative router — fixes LLM call failure on owner AI path',
        'files': [
            {'path': 'backend/api/ivx-owner-ai.ts', 'content': owner_ai_b64, 'contentEncoding': 'gzip-base64'},
        ]
    },
    'confirm': True,
    'confirmText': 'CONFIRM_IVX_GITHUB_WRITE',
}
payload_json = json.dumps(payload).encode()
print(f'Payload size: {len(payload_json)} bytes')

req = urllib.request.Request(
    'https://api.ivxholding.com/api/ivx/developer-deploy/action',
    data=payload_json,
    headers={'Content-Type':'application/json','Authorization':f'Bearer {token}'}
)
try:
    resp = json.loads(urllib.request.urlopen(req, timeout=60).read())
    print(f'Commit OK: ok={resp.get("ok")}')
except Exception as e:
    print(f'Commit FAILED: {e}')
    if hasattr(e, 'read'):
        print(f'Error: {e.read().decode()[:300]}')
PYEOF"}
